import { z } from "zod";

// The `response` object is generated by the browser's WebAuthn API
// (via @simplewebauthn/browser's startRegistration/startAuthentication) -
// it's a large, spec-defined nested structure. We only check it's present
// and looks roughly right; @simplewebauthn/server's verify functions do
// the actual cryptographic validation and will reject anything malformed.
const webauthnResponseSchema = z
  .object({
    id: z.string().min(1, "response.id is required"),
    rawId: z.string().min(1).optional(),
    type: z.string().optional(),
    response: z.record(z.string(), z.unknown()).optional(),
  })
  .passthrough();

export const registrationVerifySchema = z.object({
  response: webauthnResponseSchema,
  nickname: z.string().trim().max(50).optional(),
});

export const loginOptionsSchema = z.object({
  email: z.string().trim().email("A valid email is required"),
});

export const loginVerifySchema = z.object({
  email: z.string().trim().email("A valid email is required"),
  response: webauthnResponseSchema,
});